export const getBankLogo = (method: string): string => {
  const m = (method || '').toLowerCase();
  if (m.includes('bca')) return BANK_LOGOS.bca_va;
  if (m.includes('mandiri')) return BANK_LOGOS.mandiri_va;
  if (m.includes('bri')) return BANK_LOGOS.bri_va;
  if (m.includes('bni')) return BANK_LOGOS.bni_va;
  if (m.includes('bsi') || m.includes('bsm')) return BANK_LOGOS.bsi_va;
  if (m.includes('cimb')) return BANK_LOGOS.cimb_niaga_va;
  if (m.includes('permata')) return BANK_LOGOS.permata_va;
  if (m.includes('danamon')) return BANK_LOGOS.danamon_va;
  if (m.includes('maybank')) return BANK_LOGOS.maybank_va;
  if (m.includes('ocbc')) return BANK_LOGOS.ocbc_va;
  if (m.includes('muamalat')) return BANK_LOGOS.muamalat_va;
  if (m.includes('neo') || m.includes('bnc')) return BANK_LOGOS.bank_neo_va;
  if (m.includes('alfamart')) return BANK_LOGOS.alfamart;
  if (m.includes('indomaret')) return BANK_LOGOS.indomaret;
  if (m.includes('qris')) return BANK_LOGOS.qris;
  return BANK_LOGOS[m] || BANK_LOGOS.bri_va;
};

export const getBankDisplayName = (method: string): string => {
  const map: Record<string, string> = {
    qris: 'QRIS Dinamis',
    bca_va: 'Bank BCA',
    mandiri_va: 'Bank Mandiri',
    bri_va: 'Bank BRI',
    bni_va: 'Bank BNI',
    bsi_va: 'Bank Syariah Indonesia (BSI)',
    cimb_niaga_va: 'Bank CIMB Niaga',
    cimb_va: 'Bank CIMB Niaga',
    danamon_va: 'Bank Danamon',
    permata_va: 'Bank Permata',
    maybank_va: 'Bank Maybank',
    ocbc_va: 'Bank OCBC',
    muamalat_va: 'Bank Muamalat',
    bank_neo_va: 'Bank Neo Commerce (BNC)',
    bnc_va: 'Bank Neo Commerce (BNC)',
    alfamart: 'Alfamart Gerai Retail',
    indomaret: 'Indomaret Gerai Retail',
    payment_link: 'Payment Link'
  };
  return map[method] || String(method || '').replace('_va', ' VA').toUpperCase();
};

